#include "platform.h"
#include "state.h"
#include "gui.h"
#include "audio.h"
#include "transition.h"
#include "st_common.h"
#include "st_shared.h"
#include "st_title.h"

static struct state st_exit;
static int confirming, unavailable;
static enum xbox_exit_action selected;

static const char *labels[] = {
    "Return to launcher", "Restart game", "Reboot Xbox", "Power off Xbox"
};
static const char *details[] = {
    "Close Neverball and open your dashboard.",
    "Reload Neverball from the beginning.",
    "Restart the Xbox through its normal boot process.",
    "Save settings and turn the Xbox off."
};
enum { EXIT_CHOOSE = GUI_LAST, EXIT_CONFIRM };

static int exit_action(int token, int value)
{
    audio_play("snd/menu.ogg", 1.0f);
    if (token == GUI_BACK)
    {
        if (confirming || unavailable)
        {
            confirming = unavailable = 0;
            return exit_state(&st_exit);
        }
        return exit_state(&st_title);
    }
    if (token == EXIT_CHOOSE)
    {
        if (value < 0 || value >= 4) return 1;
        selected = (enum xbox_exit_action) value;
        unavailable = !xbox_exit_available(selected);
        confirming = !unavailable;
        return goto_state(&st_exit);
    }
    if (token == EXIT_CONFIRM && confirming)
    {
        /* Recheck the target before committing to teardown. */
        if (!xbox_exit_available(selected))
        {
            confirming = 0;
            unavailable = 1;
            return goto_state(&st_exit);
        }
        xbox_exit_select(selected);
        return 0;
    }
    return 1;
}

static int exit_enter(struct state *st, struct state *prev, int intent)
{
    int root, buttons, cancel = 0, i;
    common_init(exit_action);
    root = gui_vstack(0);
    if (root)
    {
        gui_label(root, unavailable ? "Action unavailable" :
                  confirming ? "Confirm system action" : "Exit",
                  GUI_MED, gui_wht, gui_wht);
        gui_space(root);
        if (unavailable)
        {
            gui_label(root, selected == XBOX_EXIT_LAUNCHER ?
                      "Launcher not found." : "Game executable not found.",
                      GUI_SML, gui_wht, gui_wht);
            gui_label(root, "No system action was taken.", GUI_SML, gui_wht, gui_wht);
        }
        else if (confirming)
            gui_label(root, details[selected], GUI_SML, gui_wht, gui_wht);
        else
            gui_label(root, "Choose a system action.", GUI_SML, gui_wht, gui_wht);
        gui_space(root);
        buttons = gui_varray(root);
        if (buttons)
        {
            cancel = gui_start(buttons, unavailable ? "Back" : "Cancel",
                               GUI_SML, GUI_BACK, 0);
            if (confirming)
                gui_state(buttons, labels[selected], GUI_SML, EXIT_CONFIRM, 0);
            else if (!unavailable)
                for (i = 0; i < 4; i++)
                    gui_state(buttons, labels[i], GUI_SML, EXIT_CHOOSE, i);
        }
        gui_layout(root, 0, 0);
        gui_focus(cancel);
    }
    return transition_slide(root, 1, intent);
}

static struct state st_exit = {
    exit_enter,
    common_leave,
    shared_paint,
    common_timer,
    common_point,
    common_stick,
    NULL,
    common_click,
    common_keybd,
    common_buttn
};

int xbox_exit_menu(void)
{
    confirming = unavailable = 0;
    return goto_state(&st_exit);
}
